package com.gymmind.knowledge.infrastructure.search;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import java.util.*;
@Component @ConditionalOnProperty(name="gymmind.search.vector-backend",havingValue="milvus") public class MilvusVectorIndex implements VectorIndexPort { private final Map<String,IndexedChunk> data=new HashMap<>(); public void upsert(IndexedChunk c){if(c.vector()==null||c.vector().length!=1024)throw new IllegalArgumentException("vector dimension must be 1024");data.put(c.id(),c);} public List<IndexedChunk> search(float[] q,Long t){return data.values().stream().filter(c->t.equals(c.tenantId())).sorted(Comparator.comparingDouble(c->-cos(q,c.vector()))).limit(30).toList();} public List<IndexedChunk> search(float[] q,Long t,Long u){return search(q,t).stream().filter(c->c.visibleTo(u)).toList();} public void delete(String id,Long t){data.computeIfPresent(id,(k,c)->t.equals(c.tenantId())?null:c);} private static double cos(float[]a,float[]b){double x=0,y=0,z=0;for(int i=0;i<a.length;i++){x+=a[i]*b[i];y+=a[i]*a[i];z+=b[i]*b[i];}return x/(Math.sqrt(y*z)+1e-9);} }
